<?php
namespace App\Livewire\Documents;
use App\Domain\Documents\Services\AuthorizedDocumentQuery;use App\Models\{District,DocumentCategory,DocumentType,RevenueCircle,SearchHistory};use Livewire\Attributes\Layout;use Livewire\Component;use Livewire\WithPagination;
#[Layout('layouts.app')]
class SearchDocuments extends Component{use WithPagination;public string $q='',$patta_no='',$dag_no='',$status='';public ?int $district_id=null,$revenue_circle_id=null,$document_category_id=null,$document_type_id=null,$record_year=null;public string $sort='registered_at',$direction='desc';public function updated($property):void{$this->resetPage();}public function clearFilters():void{$this->reset(['q','patta_no','dag_no','status','district_id','revenue_circle_id','document_category_id','document_type_id','record_year']);$this->resetPage();}public function render(AuthorizedDocumentQuery $authorized){abort_unless(app(\App\Domain\Authorization\Services\PermissionResolver::class)->allows(auth()->user(),'documents.view'),403);$query=$authorized->for(auth()->user())->with(['barcode','documentType','district','revenueCircle'])->when($this->q,function($x){$term=trim($this->q);$x->where(function($w)use($term){$w->where('reference_no',$term)->orWhereHas('barcode',fn($b)=>$b->where('barcode_value',$term))->orWhere('title','like','%'.$term.'%')->orWhere('landholder_name','like','%'.$term.'%')->orWhere('physical_file_reference',$term);});})->when($this->district_id,fn($x)=>$x->where('district_id',$this->district_id))->when($this->revenue_circle_id,fn($x)=>$x->where('revenue_circle_id',$this->revenue_circle_id))->when($this->document_category_id,fn($x)=>$x->where('document_category_id',$this->document_category_id))->when($this->document_type_id,fn($x)=>$x->where('document_type_id',$this->document_type_id))->when($this->patta_no,fn($x)=>$x->where('patta_no',$this->patta_no))->when($this->dag_no,fn($x)=>$x->where('dag_no',$this->dag_no))->when($this->record_year,fn($x)=>$x->where('record_year',$this->record_year))->when($this->status,fn($x)=>$x->where('status',$this->status))->orderBy(in_array($this->sort,['registered_at','record_year','reference_no'],true)?$this->sort:'registered_at',$this->direction==='asc'?'asc':'desc');$results=$query->paginate(25);return view('livewire.documents.search-documents',['documents'=>$results,'districts'=>District::where('is_active',true)->orderBy('name_en')->get(),'circles'=>RevenueCircle::where('is_active',true)->when($this->district_id,fn($x)=>$x->where('district_id',$this->district_id))->orderBy('name_en')->get(),'categories'=>DocumentCategory::where('is_active',true)->orderBy('sort_order')->get(),'types'=>DocumentType::where('is_active',true)->when($this->document_category_id,fn($x)=>$x->where('document_category_id',$this->document_category_id))->orderBy('sort_order')->get()]);}}
